# 假设检验（t检验·F检验）：独立样本t检验（含方差齐性F检验）/ 配对t检验 / 单因素方差分析ANOVA
# report 为全平铺「指标=值」结构：指标面板渲染成论文级表格，report_csv 导出 Excel 可直接打开
import io
import json
import csv as _csv
import io as _io
import numpy as np
import pandas as pd
from scipy import stats

alpha = float({{alpha}})
method = {{method}}
group_column = {{group_column}}
value_column = {{value_column}}
paired_column = {{paired_column}}
mu = float({{mu}})
tail = {{tail}}


def _to_frame(value):
    if isinstance(value, pd.DataFrame):
        return value.copy()
    if isinstance(value, bytes):
        for encoding in ('utf-8-sig', 'utf-8', 'gbk', 'gb18030'):
            try:
                return pd.read_csv(io.StringIO(value.decode(encoding)))
            except UnicodeDecodeError:
                continue
        raise RuntimeError('CSV 编码无法识别')
    if isinstance(value, str):
        return pd.read_csv(io.StringIO(value.lstrip('\ufeff')))
    raise RuntimeError('输入 data 必须是 CSV 文本或 DataFrame')


def _to_numeric(col):
    return pd.to_numeric(col, errors='coerce').astype(float)


def _fmt(v, nd=4):
    if v is None:
        return None
    try:
        f = float(v)
    except (TypeError, ValueError):
        return v
    if np.isnan(f) or np.isinf(f):
        return None
    return round(f, nd)


def _tail_p(p_two, stat, tail):
    """双尾 p → 单尾 p（stat 为带符号检验统计量）"""
    if tail == '双尾':
        return p_two
    if tail == '右尾':
        return (p_two / 2) if stat > 0 else (1 - p_two / 2)
    if tail == '左尾':
        return (p_two / 2) if stat < 0 else (1 - p_two / 2)
    return p_two


def _conclusion(p, alpha, alternative):
    if p < alpha:
        return ('在显著性水平 α=' + str(alpha) + ' 下，p 值 = ' + ('%.6f' % p) + ' < ' + str(alpha)
                + '，拒绝原假设：' + alternative + '，差异具有统计学显著性。')
    return ('在显著性水平 α=' + str(alpha) + ' 下，p 值 = ' + ('%.6f' % p) + ' ≥ ' + str(alpha)
            + '，不拒绝原假设：' + alternative + '，差异不具有统计学显著性。')


if data is None:
    raise RuntimeError('请先连接并运行上游的数据导入插件')
df = _to_frame(data)
if not 0 < alpha < 1:
    raise RuntimeError('显著性水平 alpha 必须在 0 到 1 之间')

report = {'检验方法': method, '显著性水平α': alpha}

# ═══════════════ 独立样本t检验（含方差齐性F检验） ═══════════════
if method == '独立样本t检验':
    if not group_column or not value_column:
        raise RuntimeError('请选择分组列和数值列')
    if group_column not in df.columns:
        raise RuntimeError('分组列 "' + str(group_column) + '" 不存在')
    if value_column not in df.columns:
        raise RuntimeError('数值列 "' + str(value_column) + '" 不存在')
    sub = df[[group_column, value_column]].dropna()
    if len(sub) == 0:
        raise RuntimeError('分组列与数值列没有同时非缺失的行')
    if group_column == value_column:
        raise RuntimeError('分组列和数值列不能是同一个列，请重新选择（分组列选类别列，数值列选被检验的数值列）')
    groups = {}
    for label, g in sub.groupby(group_column, sort=True):
        arr = _to_numeric(g[value_column]).dropna().to_numpy()
        if len(arr) > 0:
            groups[str(label)] = arr
    if len(groups) != 2:
        raise RuntimeError('独立样本t检验需要恰好 2 个分组，当前有 ' + str(len(groups)) + ' 组（数值列含非数字内容时该组会被剔除；组数 > 2 请改用单因素方差分析ANOVA）')
    keys = list(groups.keys())
    a, b = groups[keys[0]], groups[keys[1]]
    n1, n2 = len(a), len(b)
    m1, m2 = float(a.mean()), float(b.mean())
    s1, s2 = float(a.std(ddof=1)), float(b.std(ddof=1))
    if s1 >= s2:
        f_stat, df_num, df_den = (s1 / s2) ** 2, n1 - 1, n2 - 1
    else:
        f_stat, df_num, df_den = (s2 / s1) ** 2, n2 - 1, n1 - 1
    p_f = min(float(2 * (1 - stats.f.cdf(f_stat, df_num, df_den))), 1.0)
    equal_var = p_f >= alpha
    t_res = stats.ttest_ind(a, b, equal_var=equal_var)
    t_stat = float(t_res.statistic)
    p_two = float(t_res.pvalue)
    p_value = _tail_p(p_two, t_stat, tail)
    ci = t_res.confidence_interval(0.95)
    pooled = float(np.sqrt(((n1 - 1) * s1 ** 2 + (n2 - 1) * s2 ** 2) / (n1 + n2 - 2)))
    cohens_d = (m1 - m2) / pooled if pooled > 0 else None
    report.update({
        '分组列': group_column, '数值列': value_column,
        '样本量_总': int(n1 + n2),
        '样本量_' + keys[0]: int(n1), '样本量_' + keys[1]: int(n2),
        keys[0] + '_均值': _fmt(m1), keys[0] + '_标准差': _fmt(s1),
        keys[0] + '_最小值': _fmt(float(a.min())), keys[0] + '_最大值': _fmt(float(a.max())),
        keys[1] + '_均值': _fmt(m2), keys[1] + '_标准差': _fmt(s2),
        keys[1] + '_最小值': _fmt(float(b.min())), keys[1] + '_最大值': _fmt(float(b.max())),
        '方差齐性F检验_F统计量': _fmt(f_stat),
        '方差齐性F检验_分子自由度': int(df_num),
        '方差齐性F检验_分母自由度': int(df_den),
        '方差齐性F检验_p值': _fmt(p_f, 6),
        '方差齐性F检验_结论': '方差齐（p ≥ α，可用Student t检验）' if equal_var else '方差不齐（p < α，采用Welch t检验）',
        't检验_类型': 'Student t检验（方差齐）' if equal_var else 'Welch t检验（方差不齐修正）',
        't检验_方向': tail,
        't检验_t统计量': _fmt(t_stat),
        't检验_自由度': _fmt(t_res.df),
        't检验_p值': _fmt(p_value, 6),
        't检验_均值差': _fmt(m1 - m2),
        't检验_95%CI下限': _fmt(ci.low),
        't检验_95%CI上限': _fmt(ci.high),
        't检验_效应量Cohen_d': _fmt(cohens_d),
        '结论': _conclusion(p_value, alpha, '分组「' + keys[0] + '」与「' + keys[1] + '」的' + str(value_column) + '均值存在差异'),
    })

# ═══════════════ 配对t检验 ═══════════════
elif method == '配对t检验':
    if not value_column or not paired_column:
        raise RuntimeError('请选择前测列（数值列）和后测列（配对列）')
    if value_column not in df.columns:
        raise RuntimeError('前测列 "' + str(value_column) + '" 不存在')
    if paired_column not in df.columns:
        raise RuntimeError('后测列 "' + str(paired_column) + '" 不存在')
    if value_column == paired_column:
        raise RuntimeError('前测列和后测列不能是同一个列，请重新选择')
    sub = df[[value_column, paired_column]].dropna()
    if len(sub) == 0:
        raise RuntimeError('两列没有同时非缺失的配对样本')
    _a = _to_numeric(sub[value_column])
    _b = _to_numeric(sub[paired_column])
    _ok = _a.notna() & _b.notna()
    a = _a[_ok].to_numpy()
    b = _b[_ok].to_numpy()
    if len(a) < 2:
        raise RuntimeError('清洗非数字内容后配对样本不足 2 对')
    d = a - b
    t_res = stats.ttest_rel(a, b)
    t_stat = float(t_res.statistic)
    p_two = float(t_res.pvalue)
    p_value = _tail_p(p_two, t_stat, tail)
    ci = t_res.confidence_interval(0.95)
    sd_d = float(d.std(ddof=1))
    dz = float(d.mean()) / sd_d if sd_d > 0 else None
    report.update({
        '前测列': value_column, '后测列': paired_column,
        '配对样本数': int(len(a)),
        '前测_均值': _fmt(float(a.mean())), '前测_标准差': _fmt(float(a.std(ddof=1))),
        '后测_均值': _fmt(float(b.mean())), '后测_标准差': _fmt(float(b.std(ddof=1))),
        '差值_均值': _fmt(float(d.mean())), '差值_标准差': _fmt(sd_d),
        '差值_最小值': _fmt(float(d.min())), '差值_最大值': _fmt(float(d.max())),
        't检验_类型': '配对t检验（差值 = 前测 − 后测）',
        't检验_方向': tail,
        't检验_t统计量': _fmt(t_stat),
        't检验_自由度': int(len(a) - 1),
        't检验_p值': _fmt(p_value, 6),
        't检验_均值差': _fmt(float(d.mean())),
        't检验_95%CI下限': _fmt(ci.low),
        't检验_95%CI上限': _fmt(ci.high),
        't检验_效应量Cohen_dz': _fmt(dz),
        '结论': _conclusion(p_value, alpha, '「' + str(value_column) + '」与「' + str(paired_column) + '」的均值存在差异'),
    })

# ═══════════════ 单样本t检验 ═══════════════
elif method == '单样本t检验':
    if not value_column:
        raise RuntimeError('请选择数值列')
    if value_column not in df.columns:
        raise RuntimeError('数值列 "' + str(value_column) + '" 不存在')
    arr = _to_numeric(df[value_column]).dropna().to_numpy()
    if len(arr) < 2:
        raise RuntimeError('数值列有效样本不足 2 个')
    n = len(arr)
    mean = float(arr.mean())
    sd = float(arr.std(ddof=1))
    t_res = stats.ttest_1samp(arr, mu)
    t_stat = float(t_res.statistic)
    p_two = float(t_res.pvalue)
    p_value = _tail_p(p_two, t_stat, tail)
    ci = t_res.confidence_interval(0.95)
    cohens_d = (mean - mu) / sd if sd > 0 else None
    report.update({
        '数值列': value_column, '目标值μ0': _fmt(mu),
        '样本量': int(n),
        '样本_均值': _fmt(mean), '样本_标准差': _fmt(sd),
        '样本_最小值': _fmt(float(arr.min())), '样本_最大值': _fmt(float(arr.max())),
        't检验_类型': '单样本t检验',
        't检验_方向': tail,
        't检验_t统计量': _fmt(t_stat),
        't检验_自由度': int(n - 1),
        't检验_p值': _fmt(p_value, 6),
        't检验_均值差(样本-目标)': _fmt(mean - mu),
        't检验_均值95%CI下限': _fmt(ci.low),
        't检验_均值95%CI上限': _fmt(ci.high),
        't检验_效应量Cohen_d': _fmt(cohens_d),
        '结论': _conclusion(p_value, alpha, '「' + str(value_column) + '」的总体均值等于目标值 ' + str(mu)),
    })

# ═══════════════ 单因素方差分析（ANOVA） ═══════════════
elif method == '单因素方差分析(ANOVA)':
    if not group_column or not value_column:
        raise RuntimeError('请选择分组列和数值列')
    if group_column not in df.columns:
        raise RuntimeError('分组列 "' + str(group_column) + '" 不存在')
    if value_column not in df.columns:
        raise RuntimeError('数值列 "' + str(value_column) + '" 不存在')
    sub = df[[group_column, value_column]].dropna()
    if len(sub) == 0:
        raise RuntimeError('分组列与数值列没有同时非缺失的行')
    if group_column == value_column:
        raise RuntimeError('分组列和数值列不能是同一个列，请重新选择（分组列选类别列，数值列选被检验的数值列）')
    groups = {}
    for label, g in sub.groupby(group_column, sort=True):
        arr = _to_numeric(g[value_column]).dropna().to_numpy()
        if len(arr) > 0:
            groups[str(label)] = arr
    if len(groups) < 2:
        raise RuntimeError('ANOVA 至少需要 2 个分组，清洗非数字内容后仅剩 ' + str(len(groups)) + ' 组')
    keys = list(groups.keys())
    arrays = [groups[k] for k in keys]
    f_res = stats.f_oneway(*arrays)
    f_stat = float(f_res.statistic)
    p_value = float(f_res.pvalue)
    lev = stats.levene(*arrays)
    all_ = np.concatenate(arrays)
    grand = float(all_.mean())
    ss_between = float(sum(len(g) * (float(g.mean()) - grand) ** 2 for g in arrays))
    ss_total = float(((all_ - grand) ** 2).sum())
    eta2 = ss_between / ss_total if ss_total > 0 else None
    k, N = len(arrays), len(all_)
    report.update({
        '分组列': group_column, '数值列': value_column,
        '样本量_总': int(N), '分组数': int(k),
    })
    for i, (key, g) in enumerate(zip(keys, arrays), 1):
        report.update({
            '组' + str(i) + '_标签': key,
            '组' + str(i) + '_样本量': int(len(g)),
            '组' + str(i) + '_均值': _fmt(float(g.mean())),
            '组' + str(i) + '_标准差': _fmt(float(g.std(ddof=1))),
            '组' + str(i) + '_最小值': _fmt(float(g.min())),
            '组' + str(i) + '_最大值': _fmt(float(g.max())),
        })
    report.update({
        'Levene方差齐性检验_统计量': _fmt(lev.statistic),
        'Levene方差齐性检验_p值': _fmt(lev.pvalue, 6),
        'Levene方差齐性检验_结论': '方差齐（满足ANOVA前提）' if float(lev.pvalue) >= alpha else '方差不齐（ANOVA结果需谨慎解读）',
        'ANOVA_F统计量': _fmt(f_stat),
        'ANOVA_组间自由度': int(k - 1),
        'ANOVA_组内自由度': int(N - k),
        'ANOVA_p值': _fmt(p_value, 6),
        'ANOVA_效应量η²': _fmt(eta2),
        '结论': _conclusion(p_value, alpha, str(group_column) + '各组间的' + str(value_column) + '均值存在差异'),
    })
else:
    raise RuntimeError('未知检验方法：' + str(method))

# 原样透传数据给下游（可接数据导出插件）
if isinstance(data, str):
    out_data = data
elif isinstance(data, bytes):
    out_data = data.decode('utf-8-sig')
else:
    out_data = data.to_csv(index=False)

# report 压平成「指标,值」两列 CSV（csv 模块转义，Excel 可直接打开）
_report_rows = []


def _flatten_report(obj, prefix):
    if isinstance(obj, dict):
        for _k, _v in obj.items():
            _flatten_report(_v, prefix + str(_k) + '｜' if prefix else str(_k))
    elif isinstance(obj, list):
        for _i, _v in enumerate(obj):
            _flatten_report(_v, prefix + '[' + str(_i) + ']')
    else:
        _val = '' if obj is None else str(obj)
        _report_rows.append((prefix, _val.replace('\n', ' ').replace('\r', ' ')))


_flatten_report(report, '')
_buf = _io.StringIO()
_writer = _csv.writer(_buf, lineterminator='\n')
_writer.writerow(['指标', '值'])
for _r in _report_rows:
    _writer.writerow([_r[0], _r[1]])
report_csv = _buf.getvalue()

# 报告正文打印到运行日志（右侧面板「运行日志」可完整查看）
def _pick(keys_sub):
    return '；'.join(str(_k) + '=' + str(_v) for _k, _v in report.items()
                     if any(_s in str(_k) for _s in keys_sub) and _k not in ('结论', '检验方法'))


print('【' + str(report['检验方法']) + '】  α = ' + str(alpha))
print('样本：' + _pick(['样本量', '样本_', '配对']))
print('描述：' + _pick(['均值', '标准差', '最小', '最大']))
print('检验：' + _pick(['统计量', 'p值', '自由度', 'CI', '效应量', '方差齐性', 'Levene', 'ANOVA', 't检验_']))
print('结论：' + str(report.get('结论', '')))

return {'report': report, 'report_csv': report_csv, 'data': out_data}
